import React, { useState } from 'react';
import ProjectCard from './components/ProjectCard';
import projects from './projects';

const LOGO = 'https://img1.wsimg.com/isteam/ip/e7e3142b-3f26-4173-bc29-b2315178edb8/DI%20logo%20(2).png/:/rs=w:559,h:192,cg:true,m/cr=w:559,h:192/qt=q:95';

export default function App() {
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all');

  const liveCount = projects.filter(p => p.status === 'live').length;
  const soonCount = projects.filter(p => p.status === 'coming_soon').length;

  const filtered = projects.filter(p => {
    const matchSearch = p.name.toLowerCase().includes(search.toLowerCase()) ||
      p.description.toLowerCase().includes(search.toLowerCase()) ||
      p.tag.toLowerCase().includes(search.toLowerCase());
    const matchFilter = filter === 'all' || p.status === filter;
    return matchSearch && matchFilter;
  });

  return (
    <div style={{ minHeight: '100vh', background: '#0D0F14' }}>

      {/* Top nav bar */}
      <nav style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '0 2rem', height: 68,
        background: 'rgba(13,15,20,0.85)',
        backdropFilter: 'blur(12px)',
        borderBottom: '1px solid rgba(255,255,255,0.06)',
        position: 'sticky', top: 0, zIndex: 50,
      }}>
        <img
          src={LOGO}
          alt="DI Logo"
          style={{ height: 38, objectFit: 'contain', filter: 'brightness(1.1)' }}
        />
        <div style={{
          fontSize: 12, fontWeight: 600, color: '#4B5563',
          letterSpacing: 1, textTransform: 'uppercase',
        }}>
          ERP Portal
        </div>
      </nav>

      {/* Hero section */}
      <div style={{
        padding: '3.5rem 2rem 2rem',
        maxWidth: 960, margin: '0 auto',
        textAlign: 'center',
      }}>
        <div style={{
          display: 'inline-flex', alignItems: 'center', gap: 8,
          background: 'rgba(79,142,247,0.1)', border: '1px solid rgba(79,142,247,0.2)',
          borderRadius: 30, padding: '5px 16px', marginBottom: '1.25rem',
        }}>
          <span style={{ width: 7, height: 7, borderRadius: '50%', background: '#4F8EF7', display: 'inline-block' }} />
          <span style={{ fontSize: 12, fontWeight: 600, color: '#4F8EF7', letterSpacing: 0.5 }}>
            {liveCount} modules live · {soonCount} coming soon
          </span>
        </div>

        <h1 style={{
          fontFamily: 'Outfit, sans-serif',
          fontSize: 'clamp(28px, 5vw, 48px)',
          fontWeight: 900,
          color: '#F0F0F0',
          letterSpacing: -1,
          lineHeight: 1.1,
          marginBottom: '0.75rem',
        }}>
          Your Business,{' '}
          <span style={{
            background: 'linear-gradient(90deg, #4F8EF7, #A78BFA)',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          }}>
            One Dashboard
          </span>
        </h1>
        <p style={{ fontSize: 15, color: '#6B7280', maxWidth: 420, margin: '0 auto 2.5rem' }}>
          Access all your tools and modules from a single place.
        </p>

        {/* Stats bar */}
        <div style={{
          display: 'flex', justifyContent: 'center', gap: 12,
          flexWrap: 'wrap', marginBottom: '2.5rem',
        }}>
          {[
            { label: 'Total Modules', value: projects.length, icon: 'ti-layout-grid' },
            { label: 'Live', value: liveCount, icon: 'ti-rocket', color: '#10B981' },
            { label: 'Coming Soon', value: soonCount, icon: 'ti-clock', color: '#F59E0B' },
          ].map(s => (
            <div key={s.label} style={{
              background: 'rgba(255,255,255,0.04)',
              border: '1px solid rgba(255,255,255,0.07)',
              borderRadius: 14, padding: '0.75rem 1.5rem',
              display: 'flex', alignItems: 'center', gap: 10,
            }}>
              <i className={`ti ${s.icon}`} style={{ fontSize: 18, color: s.color || '#4F8EF7' }} />
              <div style={{ textAlign: 'left' }}>
                <div style={{ fontSize: 18, fontWeight: 800, fontFamily: 'Outfit, sans-serif', color: s.color || '#F0F0F0' }}>{s.value}</div>
                <div style={{ fontSize: 11, color: '#6B7280', letterSpacing: 0.3 }}>{s.label}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Search + filter */}
      <div style={{ maxWidth: 960, margin: '0 auto', padding: '0 2rem 1.5rem' }}>
        <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', alignItems: 'center' }}>
          <div style={{ position: 'relative', flex: 1, minWidth: 200 }}>
            <i className="ti ti-search" style={{
              position: 'absolute', left: 14, top: '50%',
              transform: 'translateY(-50%)', color: '#4B5563', fontSize: 16, pointerEvents: 'none',
            }} />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search modules..."
              style={{
                width: '100%',
                padding: '0.65rem 1rem 0.65rem 2.75rem',
                borderRadius: 12,
                border: '1px solid rgba(255,255,255,0.08)',
                background: 'rgba(255,255,255,0.04)',
                color: '#F0F0F0',
                fontSize: 14,
                outline: 'none',
              }}
            />
          </div>

          {[
            { key: 'all', label: 'All' },
            { key: 'live', label: 'Live' },
            { key: 'coming_soon', label: 'Coming Soon' },
          ].map(f => (
            <button key={f.key} onClick={() => setFilter(f.key)} style={{
              padding: '0.65rem 1.1rem',
              borderRadius: 12,
              fontSize: 13,
              fontWeight: 600,
              border: filter === f.key ? '1px solid #4F8EF7' : '1px solid rgba(255,255,255,0.08)',
              background: filter === f.key ? 'rgba(79,142,247,0.15)' : 'rgba(255,255,255,0.04)',
              color: filter === f.key ? '#4F8EF7' : '#6B7280',
              cursor: 'pointer',
              transition: 'all 0.2s ease',
            }}>
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {/* Grid */}
      <div style={{ maxWidth: 960, margin: '0 auto', padding: '0 2rem 4rem' }}>
        {filtered.length === 0 ? (
          <div style={{ textAlign: 'center', color: '#4B5563', padding: '4rem', fontSize: 14 }}>
            <i className="ti ti-search-off" style={{ fontSize: 32, display: 'block', marginBottom: 10 }} />
            No modules found.
          </div>
        ) : (
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))',
            gap: 18,
          }}>
            {filtered.map((p, i) => <ProjectCard key={p.id} project={p} index={i} />)}
          </div>
        )}

        <p style={{ marginTop: '2.5rem', textAlign: 'center', fontSize: 12, color: '#374151' }}>
          To add a project, edit{' '}
          <code style={{ background: 'rgba(255,255,255,0.05)', padding: '2px 6px', borderRadius: 4, color: '#6B7280' }}>
            src/projects.js
          </code>
        </p>
      </div>
    </div>
  );
}
